}
int binarySearch(long long int arr[], int l, int r, int x) {
  int last = r;
  if (r >= l) {
    int mid = l + (r - l) / 2;
    if (x < arr[mid] && x >= arr[mid - 1]) {
      return mid;
    }
    if (arr[mid] > x) return binarySearch(arr, l, mid - 1, x);
    return binarySearch(arr, mid + 1, r, x);
  }
  return -1;
}
