void BubbleSort(T ar[], T size) {
  for (int i = 0; i < size; i++) {
    for (int j = size - 1; j > i; j--) {
      if (ar[j] < ar[j - 1]) swap(ar[j], ar[j - 1]);
    }
  }
}
