	private static void solve() {
		int count = n/11;
		int sum = 0;
		for(int i=0;i<n;i++)
			arr[num.charAt(i)-'0']++;

		for(int i=0;i<=9;i++) {
			if(i==8) {
				if(count!=0) {
					if(arr[8]>count) {
						sum += (arr[8]-count);
						arr[8] = count;						
					}
					continue;
				}
			}
			sum += arr[i];
		}
		while(arr[8]!=0) {
			arr[8]--;
			if(sum>=10) {
				sum-=10;
				result++;
			}else break;
		}
	}
}
