vector<vector<long long> > v, sm1, sm2;
long long ans = 0;
long long n, m, x;
long long total_sum = 0;
void DFS(pair<long long, long long> a1, pair<long long, long long> b1,
         pair<long long, long long> c1, pair<long long, long long> d1,
         long long sum) {
  long long h = (c1.first - a1.first), w = (b1.second - a1.second);
  if (sum <= x) {
    cout << "a : " << a1.first << " " << a1.second << endl;
    cout << "d : " << d1.first << " " << d1.second << endl;
    cout << "sum : " << sum << endl;
    ans = max(ans, h * w);
  } else {
    if (h * w < ans || (h == 1 && w == 1)) return;
    if (h != 1) {
      DFS(a1, b1, {c1.first - 1, c1.second}, {d1.first - 1, d1.second},
          sum - (sm1[c1.first][d1.second] - sm1[c1.first][c1.second - 1]));
      DFS({a1.first + 1, c1.second}, {a1.first + 1, d1.second}, c1, d1,
          sum - (sm1[a1.first][b1.second] - sm1[a1.first][a1.second - 1]));
    }
    if (w != 1) {
      DFS(a1, {b1.first, b1.second - 1}, c1, {d1.first, d1.second - 1},
          sum - (sm2[d1.first][d1.second] - sm2[d1.first][b1.second - 1]));
      DFS({a1.first, a1.second + 1}, b1, {c1.first, c1.second + 1}, d1,
          sum - (sm2[c1.first][c1.second] - sm2[c1.first][a1.second - 1]));
    }
  }
}
void solve() {
  cin >> n >> m;
  vector<long long> aa(n), bb(m);
  read(aa);
  read(bb);
  v.assign(n + 1, vector<long long>(m + 1, 0));
  sm1.assign(n + 1, vector<long long>(m + 1, 0));
  sm2.assign(n + 1, vector<long long>(m + 1, 0));
  for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= m; ++j) v[i][j] = aa[i - 1] * bb[j - 1];
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      sm1[i][j] = sm1[i][j - 1] + v[i][j];
    }
    total_sum += sm1[i][m];
  }
  for (int j = 1; j <= m; ++j) {
    for (int i = 1; i <= n; ++i) {
      sm2[i][j] = sm2[i - 1][j] + v[i][j];
    }
  }
  cin >> x;
  cout << total_sum << endl;
  DFS(make_pair(0, 0), make_pair(0, m), make_pair(n, 0), make_pair(n, m),
      total_sum);
  cout << ans;
}
