		if(arr[9]==0)
			return false;
		arr[9]--;
		int count=10;
		for(int i=0;i<10;i++){
			if(arr[i]<count){
				count-=arr[i];
				arr[i]=0;
			}
			else{
				count=0;
				arr[i]-=count;
			}
		}
		if(count==0)
			return true;
		return false;
