import java.util.*;
import java.io.*;


public class TestClass 
{
    static class InputReader
    {
        private final InputStream stream;
        private final byte[] buf = new byte[8192];
        private int curChar, snumChars;

        public InputReader(InputStream st) 
        {
          this.stream = st;
        }

        public int read() 
        {
          if (snumChars == -1)
            throw new InputMismatchException();
          if (curChar >= snumChars) 
          {
            curChar = 0;
            try 
            {
              snumChars = stream.read(buf);
            } catch (IOException e) 
            {
              throw new InputMismatchException();
            }
            if (snumChars <= 0)
              return -1;
          }
          return buf[curChar++];
        }

        public int nextInt() 
        {
          int c = read();
          while (isSpaceChar(c)) 
          {
            c = read();
          }
          int sgn = 1;
          if (c == '-') 
          {
            sgn = -1;
            c = read();
          }
          int res = 0;
          do 
          {
            res *= 10;
            res += c - '0';
            c = read();
          } while (!isSpaceChar(c));
          return res * sgn;
        }

        public long nextLong() 
        {
          int c = read();
          while (isSpaceChar(c)) 
          {
            c = read();
          }
          int sgn = 1;
          if (c == '-') 
          {
            sgn = -1;
            c = read();
          }
          long res = 0;
          do 
          {
            res *= 10;
            res += c - '0';
            c = read();
          } while (!isSpaceChar(c));
          return res * sgn;
        }

        public int[] nextIntArray(int n) 
        {
          int a[] = new int[n];
          for (int i = 0; i < n; i++) 
          {
            a[i] = nextInt();
          }
          return a;
        }

        public String readString() 
        {
          int c = read();
          while (isSpaceChar(c)) 
          {
            c = read();
          }
          StringBuilder res = new StringBuilder();
          do 
          {
            res.appendCodePoint(c);
            c = read();
          } while (!isSpaceChar(c));
          return res.toString();
        }

        public String nextLine() 
        {
          int c = read();
          while (isSpaceChar(c))
            c = read();
          StringBuilder res = new StringBuilder();
          do 
          {
            res.appendCodePoint(c);
            c = read();
          } while (!isEndOfLine(c));
          return res.toString();
        }

        public boolean isSpaceChar(int c) 
        {
          return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) 
        {
          return c == '\n' || c == '\r' || c == -1;
        }
    }
    public static void main(String args[]) throws Exception 
    {
        InputReader in=new InputReader(System.in);
        PrintWriter w=new PrintWriter(System.out);
        int n=in.nextInt();
        String s=in.readString();
        int[] fr=new int[10];
        for(int i=0;i<n;i++)
        {
            fr[(int)s.charAt(i)-48]++;
        }
        int min=Integer.MAX_VALUE;
        //w.println(fr[8]);
        int sum=0;
        for(int i=0;i<=8;i++)
        {
            sum+=fr[i];
            if(min>fr[i] && fr[i]!=0)
            {
                min=fr[i];
            }
        }
        if(min==Integer.MAX_VALUE || fr[8]==0 || sum<11)
        {
            w.println("0");
        }
        else
            w.println(min);
        w.close();
    }
}
