import java.io.*;

public class TaskA
{
    public static void main(String[] args)
    {
        new TaskA(System.in, System.out);
    }

    private static class Solver implements Runnable
    {
        int n;
        char[] s;
        BufferedReader in;
        PrintWriter out;

        void solve() throws IOException
        {
            n = Integer.parseInt(in.readLine());
            s = in.readLine().toCharArray();

            int[] cnt = new int[10];

            for (char ch : s)
                cnt[ch - '0']++;

            int eights = cnt[8];
            int others = n - eights;
            int ans = 0;

            while (eights > 0)
            {
                eights--;
                others -= 10;
                ans++;

                if (others < 10)
                {
                    int need = (10 - others);

                    others += need;
                    eights -= need;
                }
            }

            out.println(ans);
        }

        public Solver(BufferedReader in, PrintWriter out)
        {
            this.in = in;
            this.out = out;
        }

        @Override
        public void run()
        {
            try
            {
                solve();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
        }

    }

    private TaskA(InputStream inputStream, OutputStream outputStream)
    {
        BufferedReader in = new BufferedReader(new InputStreamReader(inputStream));
        PrintWriter out = new PrintWriter(outputStream);
        Thread thread = new Thread(null, new Solver(in, out), "Solver", 1 << 27);

        try
        {
            thread.start();
            thread.join();
        }
        catch (InterruptedException e)
        {
            e.printStackTrace();
        }

        try
        {
            in.close();
        }
        catch (IOException e)
        {
            e.printStackTrace();
        }

        out.flush();
        out.close();
    }

}
