int N;
int isShrink(int i) {
  int eDigitCntLeft = 0, eDigitCntRight = 0;
  bool isLeft = true, isRight = true;
  for (int cnt = i, eDigit = 0; eDigit < 11; eDigit++) {
    if (cnt < 0 || cnt >= N) {
      isLeft = false;
      break;
    }
    if (s[cnt] == '8') eDigitCntLeft++;
    cnt--;
  }
  for (int cnt = i, eDigit = 0; eDigit < 11; eDigit++) {
    if (cnt < 0 || cnt >= N) {
      isRight = false;
      break;
    }
    if (s[cnt] == '8') eDigitCntRight++;
    cnt++;
  }
  if (isRight && isLeft) {
    if (eDigitCntLeft < eDigitCntRight)
      return 1;
    else
      return 2;
  }
  if (isRight)
    return 2;
  else if (isLeft)
    return 1;
}
