        String s = scan.next();
        for (int i = 0; i < n; i++) {

            if (s.charAt(i) == '8')
                freq8++;
        }
        n = n - freq8;

        if (freq8 != 0) {
            int count = 0;
            while (n >= 10 && freq8 > 0) {


                freq8--;
                n -= 10;
                count++;
               // System.out.println(freq8+" "+n+" "+count);
                if (n < 10 && freq8 > 1 && (10 - n) <= (freq8 - 1)) {

                    count++;
                    freq8--;
                    count+=freq8/11;
                    break;
                }


            }
            System.out.println(count);
        } else System.out.println("0");


    }

}
