inline bool checkbit(long long n, int i) { return n & (1LL << i); }
inline long long setbit(long long n, int i) { return n | (1LL << i); }
inline long long resetbit(long long n, int i) { return n & (~(1LL << i)); }
inline bool EQ(double a, double b) { return fabs(a - b) < 1e-9; }
inline bool isLeapYear(long long year) {
  return (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
}
inline bool isInside(pair<int, int> p, long long n, long long m) {
  return (p.first >= 0 && p.first < n && p.second >= 0 && p.second < m);
}
inline bool isInside(pair<int, int> p, long long n) {
  return (p.first >= 0 && p.first < n && p.second >= 0 && p.second <= n);
}
inline bool isSquare(long long x) {
  long long s = sqrt(x);
  return (s * s == x);
}
inline bool isFib(long long x) {
  return isSquare(5 * x * x + 4) || isSquare(5 * x * x - 4);
}
inline bool isPowerOfTwo(long long x) { return (x && !(x & (x - 1))); }
inline bool normal(long long &a, long long MOD) {
  a %= MOD;
  (a < 0) && (a += MOD);
}
inline long long modMul(long long a, long long b, long long MOD) {
  a %= MOD, b %= MOD;
  normal(a, MOD), normal(b, MOD);
  return (a * b) % MOD;
}
inline long long modAdd(long long a, long long b, long long MOD) {
  a %= MOD, b %= MOD;
  normal(a, MOD), normal(b, MOD);
  return (a + b) % MOD;
}
inline long long modSub(long long a, long long b, long long MOD) {
  a %= MOD, b %= MOD;
  normal(a, MOD), normal(b, MOD);
  a -= b;
  normal(a, MOD);
  return a;
}
inline long long modPow(long long b, long long p, long long MOD) {
  long long r = 1;
  while (p) {
    if (p & 1) r = modMul(r, b, MOD);
    b = modMul(b, b, MOD);
    p >>= 1;
  }
  return r;
}
inline long long modInverse(long long a, long long MOD) {
  return modPow(a, MOD - 2, MOD);
}
inline long long modDiv(long long a, long long b, long long MOD) {
  return modMul(a, modInverse(b, MOD), MOD);
}
